SELECT team_report_id, task_id, project_id, report_type, title, content, progress, status, TO_CHAR(created, 'YYYY-MM-DD') AS created, TO_CHAR(updated, 'YYYY-MM-DD') AS updated, TO_CHAR(deleted, 'YYYY-MM-DD') AS deleted
FROM team_reports
WHERE project_id = #{projectId}
